function showTrap(n) {
    [1, 2, 3].forEach(i => {
        const b = document.getElementById('btn-trap-' + i);
        if (b) b.classList.toggle('active', i === n);
    });

    const title = document.getElementById('trap-title');
    const math = document.getElementById('trap-math');
    const expl = document.getElementById('trap-expl');

    if (n === 1) {
        title.innerText = 'Danger 1: Multiplying Both Sides by 0';
        math.innerHTML = 'Start: x = 5 &bull; Multiply by 0: 0 &bull; x = 0 &bull; 5 &rArr; 0 = 0';
        expl.innerText = 'Multiplying by 0 collapses all information and artificially expands the solution set from {5} to ALL REAL NUMBERS.';
    } else if (n === 2) {
        title.innerText = 'Danger 2: Dividing by a Variable Expression';
        math.innerHTML = 'Start: x² = 3x &bull; Divide by x: x = 3 (Lost x = 0!)';
        expl.innerText = 'Dividing by x assumes x ≠ 0. If x = 0 was a valid solution (and it is, since 0² = 3(0)), dividing by x destroys that solution!';
    } else if (n === 3) {
        title.innerText = 'Danger 3: Squaring Both Sides (Extraneous Roots)';
        math.innerHTML = 'Start: x = -4 &bull; Square both sides: x² = 16 &rArr; x = ±4';
        expl.innerText = 'Squaring both sides makes negative numbers positive, creating false positive mirror solutions like x = 4 that did not exist initially.';
    }
}
